fun churn(n) { var s = "x"; while (n > 0) { s = s + "y"; n = n - 1; } return s; }
fun middle() { class Local { init(v) { this.v = v; } value() { return this.v; } } return Local(churn(6)).value(); }
fun show(a, b, c) { print a; print b; print c; }
show(churn(3), middle(), churn(2));

class Base { init(v) { this.v = v; } read() { return this.v; } }
fun factory(n) { class Leaf < Base { read() { return super.read() + 1; } extra() { return "held"; } } if (n == 0) return Leaf(5); return factory(n - 1); }
var result = factory(12); print result.read(); print result.extra();

